command:
(async () => {
  const api = game.modules.get("sinlesscsb")?.api;
  if (typeof api?.rollPools !== "function") {
    ui.notifications?.error?.("SinlessCSB: rollPools API not available.");
    return;
  }

  const tokenActor = canvas?.tokens?.controlled?.[0]?.actor ?? null;
  const actor = tokenActor ?? game.user?.character ?? null;

  if (!actor) {
    ui.notifications?.warn?.("No token selected and no owned character.");
    return;
  }

  const ownerLevel = actor.ownership?.[game.user?.id] ?? 0;
  const isOwner = ownerLevel >= CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
  if (!isOwner) {
    ui.notifications?.warn?.("Pool roll blocked: you do not own this actor.");
    return;
  }

  const isNpc = Object.prototype.hasOwnProperty.call(actor.system?.props ?? {}, "NPCinit");
  if (isNpc) {
    ui.notifications?.warn?.("Pool roll blocked: NPC actor.");
    return;
  }

  await api.rollPools({ actorUuid: actor.uuid });
})();
